(function(){
  'use strict';
  const D=window.WBData,M=window.WBModel,KEY='personal-workbench.preview.v1';
  const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(n,cls='')=>`<img class="icon ${cls}" src="assets/${n}.svg" alt="">`;
  let E,legacyBrowserBackup=null,browserReadable=true;
  let state=M.empty(),storageOK=true,route='home',platform='共用内容库',radarFilter='全部',reviewPeriod='daily',toastTimer;
  try{const raw=localStorage.getItem(KEY),parsed=raw?JSON.parse(raw):null;state=M.restore(raw);if(parsed?.version===1)legacyBrowserBackup=parsed;else try{const previous=JSON.parse(localStorage.getItem(KEY+'.before-v2')||'null');if(previous?.version===1)legacyBrowserBackup=previous;}catch{storageOK=false;}if(parsed&&![1,2].includes(parsed.version)){browserReadable=false;storageOK=false;}if(parsed?.version===1)try{if(!localStorage.getItem(KEY+'.before-v2'))localStorage.setItem(KEY+'.before-v2',raw);}catch{storageOK=false;}}catch{browserReadable=false;storageOK=false;}
  let pendingSave=null;
  function flushSave(){if(pendingSave)clearTimeout(pendingSave);pendingSave=null;try{if(!browserReadable)throw Error('旧缓存尚未读取');localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-state').textContent='已保留浏览器副本，正在保存到本机';}catch{storageOK=false;$('#storage-warning').hidden=false;$('#save-state').textContent='浏览器副本暂时无法保存';}E?.persist(state).catch(()=>{});}
  function save(debounce=false){state.modifiedAt=Date.now();if(pendingSave)clearTimeout(pendingSave);if(debounce){$('#save-state').textContent='输入已记下，停顿后保存到本机';pendingSave=setTimeout(flushSave,800);}else flushSave();}
  window.addEventListener('pagehide',()=>{if(pendingSave)flushSave();});
  function toast(t){$('#toast').textContent=!storageOK&&/保存|添加|加入/.test(t)?'本次改动仅在页面中生效，浏览器暂时无法保存。':t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
  const link=(to,text,cls='text-button')=>`<a class="${cls}" href="#${to}">${text}${icon('arrow-right')}</a>`;
  const badge=(text,tone='neutral')=>`<span class="badge ${tone}">${esc(text)}</span>`;
  const heading=(title,sub='',action='')=>`<div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
  function allTasks(){return state.tasks;}
  function tasksHTML(){return allTasks().filter(t=>t.date===M.todayKey()).map(t=>{const topic=t.sourceType==='topic'?state.topics.find(x=>x.id===t.sourceId):null;return `<div class="task-row ${t.doneAt!==null?'completed':''}"><input class="task-check" type="checkbox" id="done-${esc(t.id)}" data-task="${esc(t.id)}" aria-label="完成任务：${esc(t.title)}" ${t.doneAt!==null?'checked':''}><div class="task-main"><button class="task-content" data-action="task" data-id="${esc(t.id)}"><strong>${esc(t.title)}</strong><span>${esc(t.tag)}<span class="task-time">${icon('clock-3')}${t.minutes} 分钟</span></span></button>${topic||t.doneAt!==null||t.resultNote||t.resultEvidence?`<div class="task-followup">${topic?`<button class="text-button" data-action="topic-edit" data-id="${esc(topic.id)}" aria-label="回到选题：${esc(topic.title)}">回到选题</button>`:''}${t.doneAt!==null||t.resultNote||t.resultEvidence?`<button class="text-button" data-action="task" data-id="${esc(t.id)}">${t.resultNote||t.resultEvidence?'查看结果':'补结果与证据'}</button><span>${esc(t.verificationStatus||'待验证')}</span>`:''}</div>`:''}</div>${icon('chevron-right','task-chevron')}</div>`;}).join('');}
  function taskDetail(task){
    const topic=task.sourceType==='topic'?state.topics.find(t=>t.id===task.sourceId):null;
    modal(task.title,`<p class="dialog-lead">${esc(task.tag)} · 建议 ${task.minutes} 分钟 · ${task.doneAt!==null?'已勾选完成':'待行动'}</p>${topic?`<p class="task-origin-note">来自选题：${esc(topic.title)}</p>`:task.sourceType==='topic'?'<p class="task-origin-note">原选题已移除，任务与结果仍保留。</p>':''}<div class="detail-block"><h3>怎么做</h3><p class="pre-wrap">${esc(task.body)}</p><h3>怎样算完成</h3><p class="pre-wrap">${esc(task.evidence||'完成你为这个任务设定的动作，并留下结果与证据。')}</p></div>
      <form id="task-result-form" class="task-result-form"><input type="hidden" name="taskId" value="${esc(task.id)}"><label class="form-field">实际结果<textarea name="resultNote" rows="3" maxlength="5000" placeholder="实际做了什么，留下了什么？">${esc(task.resultNote||'')}</textarea></label><label class="form-field">结果证据<textarea name="resultEvidence" rows="2" maxlength="5000" placeholder="文件位置、公开链接或观察记录">${esc(task.resultEvidence||'')}</textarea></label><label class="form-field">核对状态<select name="verificationStatus">${['待验证','人工确认','未通过'].map(s=>`<option ${s===(task.verificationStatus||'待验证')?'selected':''}>${s}</option>`).join('')}</select></label><p class="quiet-note">勾选表示完成这项计划；已填结果和人工确认分别记录，不会自动变成已实测。这里只保存本地记录。</p><div class="dialog-actions">${['reference','benchmark','research'].includes(task.sourceType)?`<button class="outline-button" type="button" data-action="growth-open" data-kind="${esc(task.sourceType)}" data-id="${esc(task.sourceId)}">回到来源资料</button>`:''}${topic?`<button class="outline-button" type="button" data-action="topic-edit" data-id="${esc(topic.id)}">回到选题</button>`:''}${task.sourceCardId?`<button class="outline-button" type="button" data-action="distill-card" data-id="${esc(task.sourceCardId)}">回看来源卡片</button>`:''}${task.sourceType==='trial'?`<button class="outline-button" type="button" data-action="trial-record" data-id="${esc(task.id)}">工具试用记录</button>`:''}<button class="primary-button" type="submit">保存结果与证据</button></div></form>`,'任务与实际结果');
  }
  function projectHTML(p,compact=false){return `<button class="project-row ${compact?'compact':''}" data-action="project" data-id="${p.id}"><span class="project-icon ${p.id}">${icon(p.icon)}</span><span class="project-info"><span class="project-name">${p.title}</span><span class="project-next">${esc(p.next)}</span>${p.steps?`<span class="stage-track" aria-label="当前阶段：${p.stage}">${p.steps.map((s,i)=>`<span class="${i<p.current?'past':i===p.current?'current':''}" title="${s}"></span>`).join('')}</span>`:''}</span><span class="project-status">${badge(p.stage,p.id==='packrivo'?'amber':'blue')}${icon('chevron-right')}</span></button>`;}
  function toolHTML(t,full=false){return `<article class="tool-card ${full?'full':''}"><div class="tool-top"><span class="tool-mark ${t.tone}">${t.monogram}</span><div><strong>${t.name}</strong><span>${t.type}</span></div>${badge(t.label,t.tone==='amber'?'amber':'blue')}</div><button class="tool-title" data-action="tool" data-id="${t.id}">${t.title}${icon('arrow-up-right')}</button><p>${esc(full?t.summary:t.benefit)}</p><div class="tool-bottom"><span>${icon('clock-3')}${t.minutes} 分钟尝试</span><button class="small-button" data-action="tool" data-id="${t.id}">了解与试用</button></div></article>`;}
  function noteHTML(){return `<section class="notes-block"><div class="note-label">${icon('notebook-pen')}<div><h2>这个板块，我想补充…</h2><p>记录你的想法、使用感受或想调整的地方。</p></div></div><form id="note-form"><label class="sr-only" for="section-note">板块备注</label><textarea ${E?.isReady()?'':'disabled'} id="section-note" name="note" rows="2" maxlength="5000" placeholder="例如：这里我还想看到什么？">${esc(state.notes[route]||'')}</textarea><div class="note-actions"><span>输入停顿后保存到本机，浏览器留副本</span><button class="small-button" type="submit">保存备注</button></div></form></section>`;}
  function pageHeader(){const s=D.sections.find(x=>x.id===route);return `<div class="page-heading"><div><div class="page-kicker">${icon(s.icon)}${route==='home'?'我的一天':s.name}</div><h1>${route==='home'?'今天，把重要的事向前推一步。':s.name}</h1><p>${s.desc}</p></div><button class="outline-button help-toggle" data-action="section-help" aria-expanded="false">${icon('circle-help')}板块说明</button></div><div id="section-explainer" class="explainer" hidden>${icon('info')}<p>${s.help}</p></div>`;}
  function modules(items){return `<div class="module-grid">${items.map((x,i)=>`<button class="module" data-action="module" data-title="${esc(x[0])}" data-body="${esc(x[1])}"><span class="module-icon">${icon(x[2]||'file-text')}</span><strong>${x[0]}</strong><p>${x[1]}</p><span class="module-open">查看用途与内容 ${icon('arrow-up-right')}</span></button>`).join('')}</div>`;}
  function trialList(){return state.trials.length?`<div class="trial-list">${state.trials.map(id=>{const t=D.tools.find(x=>x.id===id),completed=state.tasks.some(x=>x.sourceType==='trial'&&x.sourceId===id&&x.doneAt!==null);return t?`<button class="trial-row" data-action="tool" data-id="${id}"><span class="tool-mark ${t.tone}">${t.monogram}</span><div><strong>${t.name}</strong><span>${t.trial}</span></div>${badge(completed?'已标记完成':'待尝试',completed?'teal':'blue')}</button>`:'';}).join('')}</div>`:`<div class="empty-inline">${icon('compass')}<div><strong>还没有加入工具试用</strong><p>在资讯与机会里，挑一个与你当前工作有关的工具。</p></div>${link('radar','去看看')}</div>`;}
  function render(){const s=D.sections.find(x=>x.id===route);$('#breadcrumb').textContent=s.name;document.title='我的工作台 · '+s.short;$('#nav').innerHTML=D.sections.filter(x=>x.id!=='connections'&&x.nav!==false).map((x,i)=>`${i===5?'<div class="nav-divider"><span>积累与探索</span></div>':''}<a class="nav-item ${route===x.id?'active':''}" href="#${x.id}" ${route===x.id?'aria-current="page"':''}>${icon(x.icon)}<span>${x.name}</span>${route===x.id?'<span class="nav-active-dot"></span>':''}</a>`).join('');$('#main').innerHTML=pageHeader()+(E?.views[route]||(()=>'<section class="panel">本机资料暂未连接，请启动服务后重试。</section>'))()+noteHTML();$('#storage-warning').hidden=storageOK;}
  function navigate(){const id=location.hash.slice(1)||'home';route=D.sections.some(x=>x.id===id)?id:'home';closeMenu();render();window.scrollTo(0,0);}
  function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu').setAttribute('aria-expanded','false');}
  function pauseMedia(){document.querySelectorAll('#dialog video,#dialog audio').forEach(v=>v.pause());}
  $('#dialog').addEventListener('close',pauseMedia);
  function modal(title,html,eyebrow='查看详情'){pauseMedia();$('#dialog-title')?.removeAttribute('id');$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-content').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}`;$('#dialog').showModal();}
  function detailTool(id){const t=D.tools.find(x=>x.id===id);if(!t)return;const trialTask=[...state.tasks].reverse().find(task=>task.sourceType==='trial'&&task.sourceId===id);modal(t.name,`<p class="dialog-lead">${t.title}</p>${badge(t.type,'blue')}${badge(t.source?'官方介绍 · 未实测':'栏目示例')}<div class="detail-block"><h3>它能做什么</h3><p>${esc(t.capability)}</p><h3>对你有什么帮助</h3><p>${esc(t.benefit)}</p><h3>别人拿来做什么</h3><p>${esc(t.cases)}</p></div><section class="trial-box"><div>${icon('compass')}<strong>给你的 ${t.minutes} 分钟尝试</strong></div><p>${esc(t.trial)}</p><small>看结果：${esc(t.criteria)}</small></section><div class="detail-block"><h3>使用前了解</h3><p>${esc(t.limits)}</p>${t.source?`<a class="source-link" href="${t.source}" target="_blank" rel="noopener noreferrer">${t.sourceName} ${icon('external-link')}</a>`:''}<small class="source-date">资料核查：${t.date}</small></div><div class="dialog-actions">${trialTask?`<button class="outline-button" data-action="trial-record" data-id="${esc(trialTask.id)}">补充试用结果</button>`:''}<button class="outline-button" data-action="close">先看看</button><button class="primary-button" data-action="${state.trials.includes(id)?'remove-trial':'add-trial'}" data-id="${t.id}">${icon(state.trials.includes(id)?'check':'plus')}${state.trials.includes(id)?'移出今日尝试':'加入今日尝试'}</button></div>`,'工具与尝试');}
  function searchResults(q){const all=E.search(q),results=all.slice(0,40);$('#search-results').innerHTML='<div class="search-context"><span>搜索本机已有资料 · '+all.length+' 条</span><button class="text-button" data-action="research-open" data-query="' + esc(q) + '">打开搜索与研究</button></div>'+(results.length?results.map(r=>'<button class="search-result" data-action="'+esc(r.action||'growth-open')+'" data-id="'+esc(r.id)+'" data-kind="'+esc(r.kind)+'">'+icon('search')+'<span><strong>'+esc(r.title)+'</strong><small>'+esc(r.sourceLabel)+' · '+esc(r.summary||'')+'</small></span>'+icon('chevron-right')+'</button>').join(''):'<div class="search-empty">没有找到相关内容，可以到研究页保存新的参考或主题。</div>');}
  document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(E?.handleClick(a,el))return;
    if(a==='close'){$('#dialog').close();return;}
    if(a==='section-help'){const p=$('#section-explainer');p.hidden=!p.hidden;el.setAttribute('aria-expanded',String(!p.hidden));return;}
    if(a==='guide'){modal('把这个工作台，当作你的日常入口',`<div class="detail-block"><h3>从首页开始</h3><p>今日任务可以勾选，项目可以打开查看阶段，工具推荐可以加入尝试。侧栏可进入全部八个板块。</p><h3>看不懂时，点“板块说明”</h3><p>每个板块都有用途说明；下方的备注区可以记录你想增加或调整的内容。</p><h3>哪些会保存？</h3><p>任务、试用、备注、便签和复盘在本机服务运行时保存到D盘资料文件，浏览器保留副本。AI与中转连接页可手动备份。请勿记录密码、密钥或原始客户隐私。</p><h3>这次能体验什么？</h3><p>八板块浏览、日期任务与周期复盘、跨平台共用选题卡。已整理本机项目、作品、Skill与知识入口。公开资讯可手动刷新；已支持手动AI文字和生图，只发送当次输入；真实业务账号未接入，不会自动发帖。</p></div>`,'使用说明');return;}
    if(a==='task'){const t=allTasks().find(x=>x.id===id);if(t)taskDetail(t);return;}
    if(a==='project'){const p=D.projects.find(x=>x.id===id);if(!p)return;modal(p.title,`${badge(p.stage,'blue')}<p class="dialog-lead">${p.desc}</p><div class="detail-block"><h3>下一步</h3><p>${p.next}</p><h3>目前知道什么</h3><p>${p.evidence}</p></div><div class="dialog-actions"><button class="primary-button" data-action="go" data-id="${p.route}">进入相关板块 ${icon('arrow-right')}</button></div>`,'项目进度与证据');return;}
    if(a==='tool'){if($('#dialog').open)$('#dialog').close();detailTool(id);return;}
    if(a==='remove-trial'){M.removeTrial(state,id);save();render();$('#dialog').close();toast('已移出今日尝试，可以重新加入');return;}
    if(a==='add-trial'){if(M.addTrial(state,id,(()=>{const t=D.tools.find(x=>x.id===id);return t?{title:'试一试 '+t.name,minutes:t.minutes,body:t.trial,evidence:t.criteria}:{};})())){save();render();toast('已加入今日任务，可在首页勾选完成');}$('#dialog').close();return;}
    if(a==='module'){modal(el.dataset.title,`<p class="dialog-lead">${esc(el.dataset.body)}</p><div class="detail-block"><h3>这里怎么用</h3><p>先查看这个板块需要记录的内容，再在页面下方写下你希望补充的功能。真实资料已整理在对应的项目、作品和知识入口中；这里说明这个功能如何使用。</p></div>`,'板块用途');return;}
    if(a==='platform'){platform=el.dataset.platform;render();return;}
    if(a==='radar-filter'){radarFilter=el.dataset.filter;render();return;}
    if(a==='review-period'){reviewPeriod=el.dataset.period;render();return;}
    if(a==='go'){if($('#dialog').open)$('#dialog').close();if(location.hash==='#'+id){route=id;render();}else location.hash=id;return;}
    if(a==='new-task'){modal('安排一件事',`<form id="task-form"><label class="form-field">任务日期<input type="date" name="date" required value="${M.todayKey()}"></label><label class="form-field">要做什么<input name="title" required maxlength="120" placeholder="写一个具体的小行动"></label><label class="form-field">预计时间<select name="minutes"><option value="15">15 分钟</option><option value="20">20 分钟</option><option value="25">25 分钟</option><option value="30">30 分钟</option><option value="60">60 分钟</option></select></label><p class="quiet-note">增加任务后，记得看看总时长是否适合今天。</p><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存任务</button></div></form>`,'我的安排');return;}
    if(a==='new-idea'){modal('留住一个想法',`<form id="idea-form"><label class="form-field">想法标题<input name="title" required maxlength="80" placeholder="你正在想什么？"></label><label class="form-field">再展开一点<textarea name="body" required rows="4" maxlength="1500" placeholder="写一点问题、关联或下一步想探索的内容。"></textarea></label><label class="form-field">放在哪里<select name="lane"><option>灵感收集</option><option>延伸思考</option><option>准备行动</option></select></label><div class="dialog-actions"><button class="outline-button" type="button" data-action="close">取消</button><button class="primary-button" type="submit">保存想法</button></div></form>`,'思考画板');return;}
    if(a==='search'){modal('找一件事',`<label class="sr-only" for="search-input">搜索内容</label><input id="search-input" class="search-input" placeholder="搜索选题、任务、参考与知识…" type="search" autocomplete="off"><div id="search-results"></div>`,'快速查找');searchResults('');$('#search-input').focus();}
  });
  document.addEventListener('change',ev=>{if(ev.target.matches('[data-task]'))E?.handleToggle(ev.target.dataset.task);});
  document.addEventListener('input',ev=>{if(E?.handleInput(ev.target))return;if(ev.target.id==='search-input')searchResults(ev.target.value);if(ev.target.id==='section-note'&&E?.isReady()){state.notes[route]=ev.target.value;save(true);}});
  document.addEventListener('submit',ev=>{ev.preventDefault();if(!E?.isReady()&&ev.target.matches('form')){ev.preventDefault();toast('本机记录正在连接，请稍候再保存');return;}if(E?.handleSubmit(ev.target)){ev.preventDefault();return;}if(!['note-form','task-form','idea-form','task-result-form'].includes(ev.target.id))return;ev.preventDefault();const f=new FormData(ev.target);
    if(ev.target.id==='note-form'){state.notes[route]=String(f.get('note')||'');save();toast('板块备注已保存');}

    if(ev.target.id==='task-form'){if(!M.addTask(state,String(f.get('title')),f.get('minutes'),{date:String(f.get('date')||M.todayKey())})){toast('请写一个具体任务');return;}save();$('#dialog').close();render();toast('任务已按所选日期保存');}
    if(ev.target.id==='task-result-form'){const task=M.recordTaskResult(state,String(f.get('taskId')||''),{resultNote:String(f.get('resultNote')||''),resultEvidence:String(f.get('resultEvidence')||''),verificationStatus:String(f.get('verificationStatus')||'待验证')});if(!task){toast('任务已不存在，请重新打开');return;}save();render();taskDetail(task);toast('结果与证据已保存');}
    if(ev.target.id==='idea-form'){const title=String(f.get('title')||'').trim(),body=String(f.get('body')||'').trim();if(!title||!body)return;M.addIdea(state,{title,body,lane:String(f.get('lane'))});save();$('#dialog').close();render();toast('想法已保存');}
  });
  $('#menu').addEventListener('click',()=>{const on=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',on);$('#scrim').hidden=!on;$('#menu').setAttribute('aria-expanded',String(on));});
  $('#scrim').addEventListener('click',closeMenu);
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){if($('#dialog').open){ev.preventDefault();$('#dialog').close();}closeMenu();}if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName)&&!$('#dialog').open){ev.preventDefault();$('.search-trigger').click();}});
  $('.skip-link').addEventListener('click',ev=>{ev.preventDefault();$('#main').focus();});
  D.sections.push({id:'connections',name:'AI 与中转连接',short:'AI连接',icon:'compass',desc:'手动使用文字和生图，查看连接线路与实际结果。',help:'支持手动文字与生图，由本机服务读取私有密钥。只发送当前输入；资讯抓取、模型生成与私人资料授权分别管理。'});
  E=window.WBEnrich({D,M,esc,icon,badge,heading,link,modal,toast,render,allTasks,tasksHTML,projectHTML,toolHTML,trialList,openTask:id=>{const task=allTasks().find(t=>t.id===id);if(task)taskDetail(task);},openTool:detailTool,getLegacyState:()=>legacyBrowserBackup,cacheState:()=>{if(!browserReadable)return;try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}},getState:()=>state,setState:v=>{state=v},save,go:id=>{if(location.hash==='#'+id)render();else location.hash=id},getPlatform:()=>platform,setPlatform:v=>{platform=v}});
  window.addEventListener('hashchange',navigate);navigate();E.init();
})();
